#!/usr/bin/perl
use strict;
use warnings;
use File::Find;
use File::Basename;

my $repo = '/bench/repo';
my $module = 'github.com/usememos/memos';

# symbol_id => { name, kind, pkg_path, pkg_name, recv_type, decl_file, decl_line }
my %symbols;
my @symbol_order;

# file => { package, imports => { local => full_path }, is_internal, internal_pkg_path }
my %files;

sub trim { my $s = shift; $s =~ s/^\s+|\s+$//g; $s }

sub parse_go_file {
    my ($path) = @_;
    open my $fh, '<', $path or return;
    my @lines = <$fh>;
    close $fh;

    my $pkg = '';
    my %imports;
    my $in_import = 0;
    my $import_buf = '';

    for my $i (0 .. $#lines) {
        my $line = $lines[$i];
        if ($line =~ /^package\s+(\w+)/) {
            $pkg = $1;
        }
        if ($line =~ /^\s*import\s+\(/) {
            $in_import = 1;
            $import_buf = $line;
            next if $line !~ /\)/;
        } elsif ($line =~ /^\s*import\s+"([^"]+)"/) {
            my $p = $1;
            my $local = basename($p);
            $local =~ s/[^a-zA-Z0-9_]/_/g;
            $imports{$local} = $p unless $p eq '.';
        } elsif ($in_import) {
            $import_buf .= $line;
            if ($line =~ /\)/) {
                $in_import = 0;
                while ($import_buf =~ /(?:"([^"]+)"|(\w+)\s+"([^"]+)")/g) {
                    my ($p, $alias, $p2) = ($1, $2, $3);
                    if (defined $p2) {
                        $imports{$2} = $p2;
                    } elsif (defined $p) {
                        my $local = basename($p);
                        $local =~ s/[^a-zA-Z0-9_]/_/g;
                        $imports{$local} = $p;
                    }
                }
                $import_buf = '';
            }
            next;
        }
    }

    my $is_internal = ($path =~ m{^\Q$repo\E/internal/});
    my $internal_pkg_path = '';
    if ($is_internal) {
        ($internal_pkg_path = $path) =~ s{^\Q$repo\E/}{};
        $internal_pkg_path =~ s{/[^/]+$}{};
    }

    $files{$path} = {
        package => $pkg,
        imports => \%imports,
        is_internal => $is_internal ? 1 : 0,
        internal_pkg_path => $internal_pkg_path,
        lines => \@lines,
    };

  return unless $is_internal;

    for my $i (0 .. $#lines) {
        my $line = $lines[$i];
        next unless $line =~ /^func\s+/;
        my $decl = $line;
        my $j = $i;
        while ($decl !~ /\{/ && $j < $#lines) {
            $j++;
            $decl .= $lines[$j];
        }
        $decl =~ s/\{.*//s;

        my ($recv, $name);
        if ($decl =~ /^func\s+\(([^)]*)\)\s+([A-Za-z_]\w*)\s*\(/) {
            $recv = trim($1);
            $name = $2;
        } elsif ($decl =~ /^func\s+([A-Za-z_]\w*)\s*\(/) {
            $name = $1;
        } else {
            next;
        }

        next if $name eq 'init';
        next if $name =~ /^(Test|Benchmark|Example|Fuzz)/;

        my $recv_type = '';
        if (defined $recv) {
            if ($recv =~ /(?:\*\s*)?([A-Za-z_][\w]*)\s*$/) {
                $recv_type = $1;
            }
        }

        my $kind = defined $recv ? 'method' : 'func';
        my $id = "$internal_pkg_path|$kind|$recv_type|$name";
        push @symbol_order, $id unless exists $symbols{$id};
        $symbols{$id} = {
            name => $name,
            kind => $kind,
            pkg_path => $internal_pkg_path,
            pkg_name => $pkg,
            recv_type => $recv_type,
            decl_file => $path,
            decl_line => $i + 1,
            callers => {},  # file => count
            call_sites => 0,
        };
    }
}

find({
    wanted => sub {
        return unless /\.go$/;
        parse_go_file($File::Find::name);
    },
    no_chdir => 1,
}, $repo);

# Build reverse map: full import path -> local names used across files
my %path_to_locals;  # full_path -> { local_name => 1 }

for my $fpath (keys %files) {
    my $imports = $files{$fpath}{imports};
    for my $local (keys %$imports) {
        my $full = $imports->{$local};
        next unless $full =~ m{^$module/internal/} || $full =~ m{^internal/};
        my $rel = $full;
        $rel =~ s/^$module\///;
        $path_to_locals{$rel}{$local} = 1;
    }
}

sub strip_comments {
    my ($text) = @_;
    $text =~ s{//.*$}{}mg;
    $text =~ s{/\*.*?\*/}{}sg;
    return $text;
}

sub count_calls_in_file {
    my ($fpath, $sym) = @_;
    my $info = $files{$fpath};
    return 0 unless $info;

    my $text = join('', @{ $info->{lines} });
    $text = strip_comments($text);

    my $name = $sym->{name};
    my $pkg_path = $sym->{pkg_path};
    my $kind = $sym->{kind};
    my $count = 0;

    if ($kind eq 'func') {
        my @patterns;
        if ($info->{is_internal} && $info->{internal_pkg_path} eq $pkg_path) {
            push @patterns, qr/(?<![.\w])\Q$name\E\s*\(/;
        }
        my $locals = $path_to_locals{$pkg_path} || {};
        for my $local (keys %$locals) {
            next unless exists $info->{imports}{$local};
            push @patterns, qr/(?<![.\w])\Q$local\E\.\Q$name\E\s*\(/;
        }
        for my $pat (@patterns) {
            while ($text =~ /$pat/g) { $count++; }
        }
    } else {
        # method: count .MethodName( in files that import this package OR same package
        my $imports_pkg = ($info->{is_internal} && $info->{internal_pkg_path} eq $pkg_path);
        my $locals = $path_to_locals{$pkg_path} || {};
        my $has_import = 0;
        for my $local (keys %$locals) {
            if (exists $info->{imports}{$local}) { $has_import = 1; last; }
        }
        if ($imports_pkg || $has_import) {
            my $pat = qr/\.\Q$name\E\s*\(/;
            while ($text =~ /$pat/g) { $count++; }
        }
    }

    # subtract declaration line in declaring file
    if ($fpath eq $sym->{decl_file}) {
        my $decl_line = $files{$fpath}{lines}[ $sym->{decl_line} - 1 ];
        $decl_line = strip_comments($decl_line);
        if ($kind eq 'func' && $decl_line =~ /\b\Q$name\E\s*\(/) {
            $count-- if $count > 0;
        } elsif ($kind eq 'method' && $decl_line =~ /\)\s*\Q$name\E\s*\(/) {
            $count-- if $count > 0;
        }
    }

    return $count;
}

for my $id (@symbol_order) {
    my $sym = $symbols{$id};
    for my $fpath (keys %files) {
        my $c = count_calls_in_file($fpath, $sym);
        if ($c > 0) {
            $sym->{callers}{$fpath} = $c;
            $sym->{call_sites} += $c;
        }
    }
}

my @ranked = sort {
    $symbols{$b}{call_sites} <=> $symbols{$a}{call_sites}
        || $symbols{$a}{pkg_path} cmp $symbols{$b}{pkg_path}
        || $symbols{$a}{name} cmp $symbols{$b}{name}
} @symbol_order;

print "TOP 30 BY CALL SITES (fan-in)\n";
print "=" x 80, "\n";
for my $i (0 .. 29) {
    last unless defined $ranked[$i];
    my $s = $symbols{ $ranked[$i] };
  my $recv = $s->{recv_type} ? "($s->{recv_type})" : '';
  my $distinct_callers = scalar keys %{ $s->{callers} };
  printf "%3d. %d sites, %d caller files: %s.%s%s  [%s:%d]\n",
    $i+1, $s->{call_sites}, $distinct_callers,
    $s->{pkg_name}, $recv, $s->{name},
    $s->{decl_file}, $s->{decl_line};
}

# Also show top by distinct caller files
my @by_callers = sort {
    scalar(keys %{ $symbols{$b}{callers} }) <=> scalar(keys %{ $symbols{$a}{callers} })
        || $symbols{$b}{call_sites} <=> $symbols{$a}{call_sites}
} @symbol_order;

print "\nTOP 15 BY DISTINCT CALLER FILES\n";
print "=" x 80, "\n";
for my $i (0 .. 14) {
    my $s = $symbols{ $by_callers[$i] };
    my $recv = $s->{recv_type} ? "($s->{recv_type})" : '';
    printf "%3d. %d files, %d sites: %s.%s%s\n",
      $i+1, scalar(keys %{ $s->{callers} }), $s->{call_sites},
      $s->{pkg_name}, $recv, $s->{name};
}

# Detail for winner
my $winner = $symbols{ $ranked[0] };
print "\nWINNER DETAIL\n";
print "=" x 80, "\n";
my $recv = $winner->{recv_type} ? "($winner->{recv_type})" : '';
print "Symbol: $winner->{pkg_name}$recv.$winner->{name}\n";
print "Declaration: $winner->{decl_file}:$winner->{decl_line}\n";
print "Call sites: $winner->{call_sites}\n";
print "Caller files:\n";
for my $f (sort { $winner->{callers}{$b} <=> $winner->{callers}{$a} } keys %{ $winner->{callers} }) {
    my $rel = $f; $rel =~ s{^\Q$repo\E/}{};
    printf "  %4d  %s\n", $winner->{callers}{$f}, $rel;
}

