    $symbols{$b}{call_sites} <=> $symbols{$a}{call_sites}
        || $symbols{$a}{pkg_path} cmp $symbols{$b}{pkg_path}
        || $symbols{$a}{name} cmp $symbols{$b}{name}
} @symbol_order;

print "TOP 30 BY CALL SITES (fan-in)\n";
print "=" x 80, "\n";
for my $i (0 .. 29) {
    last unless defined $ranked[$i];
    my $s = $symbols{ $ranked[$i] };
  my $recv = $s->{recv_type} ? "($s->{recv_type})" : '';
  my $distinct_callers = scalar keys %{ $s->{callers} };
  printf "%3d. %d sites, %d caller files: %s.%s%s  [%s:%d]\n",
    $i+1, $s->{call_sites}, $distinct_callers,
    $s->{pkg_name}, $recv, $s->{name},
